INSERT INTO official_exams (id, cefr_level, title, title_tr, title_en, source, questions, kind, skill, variant, sort_order, scoring, time_limit_minutes)
VALUES ($tt$testest-sample-b1-reading$tt$, $tt$B1$tt$, $tt$B1 tasemeeksami näidistest: lugemine$tt$, $tt$B1 sınav örneği: okuma$tt$, $tt$B1 sample exam: reading$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, $tt$[{"section":"1. ülesanne","group":"182-0","sourceTitle":"Lugemistesti 1. ülesanne, 1.-9. küsimus","prompt":"1. Mitmes poes üle Eesti müüakse meestele hea hinnaga riideid. __(1)__","context":"Loe lauseid (1-9) ja leia iga lausega sobiv kuulutus (A–F). **A** **B** Aitame lastel sportida!\nToeta mõne euroga laste jalgrattasporti.\nSinu abiga saame osta spordikoolidele kvaliteetsed jalgrattad.\nRaha korjatakse kõigis suuremates kaubanduskeskustes ja bensiinijaamades üle Eesti.\nTäpsem info:\nwww.heategevusfond.ee Rõivafirma MOOD\nKauplustes on 26. augustist kuni 15. septembrini suur soodustusmüük.\nMüüme vana kauba odavalt maha\nja paneme müügile\nuue sügiskollektsiooni!\nMeeste kampsunid\nalates 3 ja püksid alates 6 eurost!\nSuur valik eri mustriga triiksärke!\nKülastage meie poode Pärnus, Tartus\nja Viljandis.\nwww.fashion.ee **C** **D** Kallid lapsed!\nLasteajakiri Sõber Koer ootab\nteid osalema fotokonkursil\n\"Minu kõige suurem sõber\".\nTee oma lemmikloomast foto ja\nsaada toimetusse aadressil\nsoberkoer@ajakiri.ee\nValime lugejate abiga välja 10 paremat fotot ja jagame auhindu!\nTingimustest loe täpsemalt\nmeie uuest numbrist. Müügile on jõudnud uus loomaajakiri MEIE LOOM\nMeie Loom on mõeldud inimesele,\nkes võtab esimest korda endale lemmiklooma.\nAjakiri annab nõu, millist tõugu looma valida, mida peab loomapidaja teadma ja kuidas uue pereliikme eest hoolitseda.\nLisaks palju fotosid kuulsate inimeste lemmikloomadest.\nTellimine aadressil\nmeieloom@ajakiri.ee **E** **F** Tallinna Kaubamaja kutsub abistama suurte perede lapsi ning tooma vähekasutatud lasterõivad ja -jalatsid kaubamajja.\nEriti oodatud on talveriided ja -jalatsid.\nTerve ja puhas kaup võetakse vastu kaubamaja esimesel korrusel\niga päeval kella 9:00-18:00. Astu moodsalt!\nKauplustekett Kuldne King avab uued poed ja uuendab oma kollektsiooni.\nMüügil soodsa hinnaga mugavad jalanõud kogu perele, lisaks suur valik naiste käekotte.\nUued poed on avatud\nTallinnas Viru tänav 8\nPärnus Rüütli tänav 5\nAvamise puhul palju soodsaid\npakkumisi ja üllatusi!\n\nVali lausega sobiv kuulutus.\n\n1. Mitmes poes üle Eesti müüakse meestele hea hinnaga riideid. __(1)__\n2. Ajakiri kutsub pilte tegema ja korraldab fotovõistluse. __(2)__\n3. Heade inimeste abiga saavad lapsed sportima hakata. __(3)__\n4. Varsti avatakse pood, kus on uus kollektsioon jalatseid. __(4)__\n5. Ajakiri neile, kellel pole varem lemmikloomi olnud. __(5)__\n6. Et uue kauba saaks müüki panna, tuleb vana enne maha müüa. __(6)__\n7. Kaubanduskeskustes kogutakse laste abistamiseks raha. __(7)__\n8. Too abivajajatele oma jalanõud, mida sa ise ei kanna. __(8)__\n9. Ajakirja uues numbris on fotod tuntud inimeste koduloomadest. __(9)__","gap":1,"explanation":"","type":"multiple_choice","options":["A","B","C","D","E","F"],"correctIndex":1},{"section":"1. ülesanne","group":"182-0","sourceTitle":"Lugemistesti 1. ülesanne, 1.-9. küsimus","prompt":"2. Ajakiri kutsub pilte tegema ja korraldab fotovõistluse. __(2)__","context":"Loe lauseid (1-9) ja leia iga lausega sobiv kuulutus (A–F). **A** **B** Aitame lastel sportida!\nToeta mõne euroga laste jalgrattasporti.\nSinu abiga saame osta spordikoolidele kvaliteetsed jalgrattad.\nRaha korjatakse kõigis suuremates kaubanduskeskustes ja bensiinijaamades üle Eesti.\nTäpsem info:\nwww.heategevusfond.ee Rõivafirma MOOD\nKauplustes on 26. augustist kuni 15. septembrini suur soodustusmüük.\nMüüme vana kauba odavalt maha\nja paneme müügile\nuue sügiskollektsiooni!\nMeeste kampsunid\nalates 3 ja püksid alates 6 eurost!\nSuur valik eri mustriga triiksärke!\nKülastage meie poode Pärnus, Tartus\nja Viljandis.\nwww.fashion.ee **C** **D** Kallid lapsed!\nLasteajakiri Sõber Koer ootab\nteid osalema fotokonkursil\n\"Minu kõige suurem sõber\".\nTee oma lemmikloomast foto ja\