INSERT INTO official_exams (id, cefr_level, title, title_tr, title_en, source, questions, kind, skill, variant, sort_order, scoring, time_limit_minutes)
VALUES ($tt$testest-diagnostic-b1-reading-3$tt$, $tt$B1$tt$, $tt$B1 diagnoostest: lugemine (3. variant)$tt$, $tt$B1 tanı testi: okuma (3. varyant)$tt$, $tt$B1 diagnostic: reading (variant 3)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, $tt$[{"section":"1. ülesanne","group":"213-0","sourceTitle":"Lugemistesti 1. ülesanne, 1. küsimus","type":"multiple_choice","prompt":"Millises keeles oskab mees ainult lugeda?","context":"Loe teksti ja leia küsimusele õige vastus. „Tahaksin kindlasti uuel aastal minna mõnd võõrkeelt õppima,” räägib Mark. „Mu emakeel on inglise keel ja sellega saab küll peaaegu kõikjal hakkama, aga minu arust sellest ei piisa. Tegelikult saan natukene aru eesti keelest. Kui loen lehti, siis saan aru, mis seal kirjas on, aga ise seda keelt ei räägi ega saa ka eestlaste kiirest jutust midagi aru. Vene keelega saan hakkama, seda ma loen, kirjutan ja ka räägin. Mu vanaema on venelane. Mõtlen, et hea oleks osata veel itaalia keelt, sest seda räägivad nii paljud inimesed maailmas.”","options":["Itaalia keeles","Vene keeles","Eesti keeles"],"correctIndex":2,"explanation":""},{"section":"1. ülesanne","group":"213-1","sourceTitle":"Lugemistesti 1. ülesanne, 2. küsimus","type":"multiple_choice","prompt":"1950. aastatel tegutses hoones","context":"Loe teksti ja leia küsimusele õige vastus. Lasteaed ja päevakeskus on selles majas olnud juba paarkümmend aastat. Tegelikult ehitati see hoone kunagi 1930. aastatel hoopis tütarlaste kooliks. Hoones olid suured klassiruumid ja mitu söögituba. Kui kool 1950. aastatel oma tegevuse lõpetas, kolis sinna laste muusikakool. Pärast seda, väga lühikest aega, oli majas ka lastehaigla. Maja oli väga halvas seisus. Alles siis, kui lasteaed sinna kolis, tehti hoone korda ja nüüd näeb see välja selline nagu algusaastatel.","options":["tütarlaste kool.","laste muusikakool.","lasteaed ja päevakeskus."],"correctIndex":1,"explanation":""},{"section":"1. ülesanne","group":"213-2","sourceTitle":"Lugemistesti 1. ülesanne, 3. küsimus","type":"multiple_choice","prompt":"Veneetsia karnevali ajal on ilm tavaliselt","context":"Loe teksti ja leia küsimusele õige vastus. Itaalias on igas piirkonnas erinev temperatuur. Turistidel soovitatakse seepärast enne reisi kindlasti ilmateadet vaadata. Kui Roomas on talved mahedad ja soojad, siis Veneetsias on need vihmased ja udused. Kõigest hoolimata armastavad turistid just sel aastaajal Veneetsiat külastada, sest siis on seal kuulus karneval. Ka kesksuvel pole kõige parem Veneetsiasse minna, sest sel ajal on seal õhk liiga niiske. Kevadel aga võivad seal puhuda väga külmad tuuled. Tegelikult ei ole ükski turist siiani ilmast hoolinud.","options":["vihmane ja udune.","soe ja mahe.","külm ja tuuline."],"correctIndex":0,"explanation":""},{"section":"1. ülesanne","group":"213-3","sourceTitle":"Lugemistesti 1. ülesanne, 4. küsimus","type":"multiple_choice","prompt":"Milline laul tuleb ettekandele esimest korda?","context":"Loe teksti ja leia küsimusele õige vastus. Jõuluajal saab kirikutes kuulata taas kaunist muusikat. Esimest korda esinevad koos Siiri Sisask ja Tõnis Mägi. Kontserdituuril „Jõulutähed” esitavad solistid oma uuemat ja ka vanemat loomingut. Esmaesituses saab kuulda näiteks Siiri Sisaski lugu „Aastaring”, mis on pärit tema viimaselt plaadilt. Ka Tõnis Mägil on oma kuulajale pakkuda midagi täiesti uut, kuid selle jätab ta esialgu saladuseks. Vanemast loomingust tuleb esitusele aga näiteks „Talveöö”. Kontsertidel kõlavad lood on inspireeritud jõulu- ja talveajast. Kontserdilt saab osta ka mõlema laulja heliplaate.","options":["„Aastaring”","„Jõulutähed”","„Talveöö”"],"correctIndex":0,"explanation":""},{"section":"1. ülesanne","group":"213-4","sourceTitle":"Lugemistesti 1. ülesanne, 5. küsimus","type":"multiple_choice","prompt":"Esmaabi eksam on kohustuslik","context":"Loe teksti ja leia küsimusele õige vastus. Eesti autokoolides peavad kõik algajad autojuhid läbima ka esmaabi koolituse. See on kohustuslik ja lõpeb eksamiga. Koolitus kestab kuusteist tundi. Austrias näiteks kestab samasugune koolitus kuus ja Saksamaal neli tundi. Kuigi nende maades pole see kohustuslik, nagu meil on. Prantsusmaal aga õpitakse esmaabi andma juba põhikoolis ja autokoolis seda eksamit pole. Ka Eestis võiks esmaabi andmist juba põhikoolis õpetada, siis oskaksid kõik inimesed õnnetusse sattudes õigesti toimida.","options":["Saksamaal.","Eestis.","Prantsusmaal."],"correctIndex":1,"explanation":""},{"section":"1. ülesanne","group":"213-5","sourceTitle":"Lugemistesti 1. ülesanne, 6. küsimus","type":"multiple_choice","prompt":"Kes valiti valla parimaks sportlaseks?","context":"Loe teksti ja leia küsimusele õige vastus. Detsembris selgusid Raasiku valla parimad sportlased. Heade saavutustega silma paistnud sportlastele anti pidulikul koosolemisel üle tänukiri ja preemiad: parimale sportlasele rahaline preemia, paremuselt järgmisele auhinnareis Lapimaale ja kolmanda koha omanikule jalgratas. Rahalise preemia sai maletaja Margus Kask, kes oli saavutanud sel aastal Eesti meistrivõistlustel esikoha. Auhinnareisile sõidab jalgrattur Tarmo Tali, kes võitis kevadel Euroopa karika. Uue jalgratta saab kahekordne Eesti noortemeister, ujuja Marek Tulp.","options":["Jalgrattur","Maletaja","Ujuja"],"correctIndex":1,"explanation":""},{"section":"1. ülesanne","group":"213-6","sourceTitle":"Lugemistesti 1. ülesanne, 7. küsimus","type":"multiple_choice","prompt":"Inimestele meeldib kõige enam saata","context":"Loe teksti ja leia küsimusele õige vastus. E-kirja kirjutamine on tänapäeval nii igapäevane, et teistmoodi ei saakski enam suhelda. Kui palju on aga neid, kellele meeldib käsitsi kirju kirjutada, neile ümbrik ja mark otsida ja siis posti panna? Selgus, et eestimaalastele meeldib lähedastele kirju kirjutada. Möödunud aastal saadeti ligi 60 miljonit kirja. Samuti armastavad inimesed oma sõpru ja tuttavaid kaardiga meeles pidada. Neid saadetakse just pühade ajal palju, aga siiski veidi vähem kui kirju. Postipakid on juba kulukamad ja seepärast saadetakse neid harva. Kui aga saadetakse, siis kõige rohkem välismaale. Nii et kirjade, kaartide ja pakkide saatmine pole sugugi ajalukku jäänud, vastupidi.","options":["pakke välismaale.","kaarte sõpradele.","kirju lähedastele."],"correctIndex":2,"explanation":""},{"section":"2. ülesanne","group":"213-7","sourceTitle":"Lugemistesti 2. ülesanne, 8.-15. küsimus","prompt":"8. Selles huvikoolis võivad käia kõik linna lapsed. __(8)__","context":"Loe tekst läbi ja otsusta, kas teksti kohta esitatud väited on õiged või valed. **Huvikool aitab lapsel aega veeta**\nTartu Jakobi huvikoolis saavad lapsed pärast tunde kokku, et tegeleda muusika või kunstiga või õppida keeli. Selles koolis on päris eriline ringide valik, näiteks õpetatakse siin vanaaegset tantsu, savinõude tegemist, puu- ja metallitööd, aga ka ladina ja kreeka keelt. Sobiva ajaviite leiavad nii poisid kui ka tüdrukud.\nHuviringid tegutsevad Tartu katoliku kooli juures ning on selle kooli õpilaste tavapärane vaba aja veetmise koht. Muidugi on huviringidesse oodatud ka teiste koolide õpilased.\nMuusikaringi juhi õpetaja Sepa arvates on huviharidus, igasugune hobidega tegelemine sama oluline kui kooliskäimine. Igal lapsel peaks selleks võimalus olema. Sepa arvates on tähtis tekitada lastes huvi asjade vastu, mida tavakoolis ehk õppida ei saa. Huviringis ei õpita ainult laulma või pilli mängima, vaid näiteks ka pille meisterdama. Lapsed, kes siin käivad, ei taha kõik sugugi muusikuks või kunstnikuks saada. Aga nad õpivad kunsti hindama ja armastama.\nHuvikool ei ole siiski ainult lastele. Siin töötab ka täiskasvanutele mõeldud ringe. Täiskasvanute stuudios Vaikuse Muusika õpitakse vanamuusikat, koorilaulu, lisaks metallikunsti, keraamikat ja puutööd. Aga täiskasvanutele ja lastele on ka ühiseid ringe, näiteks male- ja keeleringid.\nLisaks omapärastele huviringidele on Jakobi huvikool nii mitmeski muus mõttes eriline. See on näiteks Eestis ainus kool, kus meesõpetajaid on rohkem kui naisi. Ehk just seepärast on huvikool ka poiste hulgas väga populaarne!\nHuviringis osalemine maksab 12−23 eurot kuus. Tasu suurus oleneb sellest, mitu korda nädalas kokku saadakse. Täiskasvanute huviringid ei ole palju kallimad. Koorilaulja ühe kuu tasu on neile aga ainult 3,50 eurot. Huvikooli tegevust toetab Tartu linn, seepärast ongi osavõtt ringide tööst üsna soodne.\n\nKas väide on õige või vale?\n\n8. Selles huvikoolis võivad käia kõik linna lapsed. __(8)__\n9. Õpetaja Sepa arvates on hobid ja kool võrdselt tähtsad. __(9)__\n10. Huvikoolis õpitakse samu asju nagu tavalises koolis. __(10)__\n11. Siin kasvatatakse tulevasi muusikuid ja kunstnikke. __(11)__\n12. Kõige rohkem on selles koolis võõrkeeleringe. __(12)__\n13. Täiskasvanutele ja lastele on ka ühiseid ringe. __(13)__\n14. Huvikoolis töötab rohkem meesõpetajaid. __(14)__\n15. Kuumakse on soodne nii lastele kui ka täiskasvanutele. __(15)__","gap":8,"explanation":"","type":"multiple_choice","options":["õige","vale"],"correctIndex":0},{"section":"2. ülesanne","group":"213-7","sourceTitle":"Lugemistesti 2. ülesanne, 8.-15. küsimus","prompt":"9. Õpetaja Sepa arvates on hobid ja kool võrdselt tähtsad. __(9)__","context":"Loe tekst läbi ja otsusta, kas teksti kohta esitatud väited on õiged või valed. **Huvikool aitab lapsel aega veeta**\nTartu Jakobi huvikoolis saavad lapsed pärast tunde kokku, et tegeleda muusika või kunstiga või õppida keeli. Selles koolis on päris eriline ringide valik, näiteks õpetatakse siin vanaaegset tantsu, savinõude tegemist, puu- ja metallitööd, aga ka ladina ja kreeka keelt. Sobiva ajaviite leiavad nii poisid kui ka tüdrukud.\nHuviringid tegutsevad Tartu katoliku kooli juures ning on selle kooli õpilaste tavapärane vaba aja veetmise koht. Muidugi on huviringidesse oodatud ka teiste koolide õpilased.\nMuusikaringi juhi õpetaja Sepa arvates on huviharidus, igasugune hobidega tegelemine sama oluline kui kooliskäimine. Igal lapsel peaks selleks võimalus olema. Sepa arvates on tähtis tekitada lastes huvi asjade vastu, mida tavakoolis ehk õppida ei saa. Huviringis ei õpita ainult laulma või pilli mängima, vaid näiteks ka pille meisterdama. Lapsed, kes siin käivad, ei taha kõik sugugi muusikuks või kunstnikuks saada. Aga nad õpivad kunsti hindama ja armastama.\nHuvikool ei ole siiski ainult lastele. Siin töötab ka täiskasvanutele mõeldud ringe. Täiskasvanute stuudios Vaikuse Muusika õpitakse vanamuusikat, koorilaulu, lisaks metallikunsti, keraamikat ja puutööd. Aga täiskasvanutele ja lastele on ka ühiseid ringe, näiteks male- ja keeleringid.\nLisaks omapärastele huviringidele on Jakobi huvikool nii mitmeski muus mõttes eriline. See on näiteks Eestis ainus kool, kus meesõpetajaid on rohkem kui naisi. Ehk just seepärast on huvikool ka poiste hulgas väga populaarne!\nHuviringis osalemine maksab 12−23 eurot kuus. Tasu suurus oleneb sellest, mitu korda nädalas kokku saadakse. Täiskasvanute huviringid ei ole palju kallimad. Koorilaulja ühe kuu tasu on neile aga ainult 3,50 eurot. Huvikooli tegevust toetab Tartu linn, seepärast ongi osavõtt ringide tööst üsna soodne.\n\nKas väide on õige või vale?\n\n8. Selles huvikoolis võivad käia kõik linna lapsed. __(8)__\n9. Õpetaja Sepa arvates on hobid ja kool võrdselt tähtsad. __(9)__\n10. Huvikoolis õpitakse samu asju nagu tavalises koolis. __(10)__\n11. Siin kasvatatakse tulevasi muusikuid ja kunstnikke. __(11)__\n12. Kõige rohkem on selles koolis võõrkeeleringe. __(12)__\n13. Täiskasvanutele ja lastele on ka ühiseid ringe. __(13)__\n14. Huvikoolis töötab rohkem meesõpetajaid. __(14)__\n15. Kuumakse on soodne nii lastele kui ka täiskasvanutele. __(15)__","gap":9,"explanation":"","type":"multiple_choice","options":["õige","vale"],"correctIndex":0},{"section":"2. ülesanne","group":"213-7","sourceTitle":"Lugemistesti 2. ülesanne, 8.-15. küsimus","prompt":"10. Huvikoolis õpitakse samu asju nagu tavalises koolis. __(10)__","context":"Loe tekst läbi ja otsusta, kas teksti kohta esitatud väited on õiged või valed. **Huvikool aitab lapsel aega veeta**\nTartu Jak