INSERT INTO official_exams (id, cefr_level, title, title_tr, title_en, source, questions, kind, skill, variant, sort_order, scoring, time_limit_minutes)
VALUES ($tt$testest-diagnostic-b1-writing-4$tt$, $tt$B1$tt$, $tt$B1 diagnoostest: kirjutamine (4. variant)$tt$, $tt$B1 tanı testi: yazma (4. varyant)$tt$, $tt$B1 diagnostic: writing (variant 4)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, $tt$[{"section":"1. ülesanne","group":"230-0","sourceTitle":"Kirjutamistesti 1. ülesanne, 1.-10. küsimus","prompt":"Mis ühendab häid sõpru Jaagupit, Tiitu ja Kaarlit? Vastus: võimsad mootorrattad ja sõprus. Sõpru on tegelikult rohkem kui kolm ja seltskonda **(1)** (kuulun, kuulub, kuulud) __(1)__ veel tuntud popmuusikuid, ooperilauljaid ja näitlejaid.","context":"Loe teksti. Vali sulgudes olevate sõnade hulgast välja sobiv ning kirjuta see lünka.\n\nMotomehed\n\nMis ühendab häid sõpru Jaagupit, Tiitu ja Kaarlit? Vastus: võimsad mootorrattad ja sõprus. Sõpru on tegelikult rohkem kui kolm ja seltskonda **(1)** (kuulun, kuulub, kuulud) __(1)__ veel tuntud popmuusikuid, ooperilauljaid ja näitlejaid.\nKaks aastat **(2)** (tagasi, edasi, mööda) __(2)__ läksid sõbrad esimesele motomatkale. Selle eesmärk oli koguda abivajajatele **(3)** (raha, rahast, rahale) __(3)__\nIga aastaga on aga juurde tulnud firmasid, **(4)** (keda, kelleks, kes) __(4)__ selleks reisiks raha annetavad. Selle eest siis heategusid tehaksegi.\nTänavune motomatk viis mehed Pihkvasse. Seekord **(5)** (abistasid, leidsid, korjasid) __(5)__ nad kohalikku Jaani kirikut, mille taastamiseks oli kogutud 2500 eurot.\nMehed on Eesti küll otsast otsani **(6)** (läbi, kaudu, üle) __(6)__ sõitnud, aga ometi on alati midagi üllatavat. Palju on säilinud haruldasi paiku, mis on tõeliselt **(7)** (kaunite, kauneid, kaunid) __(7)__.\nIisakul külastati ka üht lastekodu, **(8)** (mida, mis, mille) __(8)__ tegi mehed kurvaks. See-eest rõõmustasid lapsed väga mootorratastega külaliste üle. Kõige **(9)** (parem, suurem, rohkem) __(9)__ huvi tekitas lastes mootorrattasõit.\nSõbrad leiavad, **(10)** (sest, et, kuid) __(10)__ see matk on ilus ettevõtmine. Selle tulemusel saavad näiteks kirikud uued aknad ja lapsed midagi vajalikku.","gap":1,"explanation":"","type":"text_gap","options":[],"accepted":["kuulub"],"correctIndex":-1},{"section":"1. ülesanne","group":"230-0","sourceTitle":"Kirjutamistesti 1. ülesanne, 1.-10. küsimus","prompt":"Kaks aastat **(2)** (tagasi, edasi, mööda) __(2)__ läksid sõbrad esimesele motomatkale. Selle eesmärk oli koguda abivajajatele **(3)** (raha, rahast, rahale) ___","context":"Loe teksti. Vali sulgudes olevate sõnade hulgast välja sobiv ning kirjuta see lünka.\n\nMotomehed\n\nMis ühendab häid sõpru Jaagupit, Tiitu ja Kaarlit? Vastus: võimsad mootorrattad ja sõprus. Sõpru on tegelikult rohkem kui kolm ja seltskonda **(1)** (kuulun, kuulub, kuulud) __(1)__ veel tuntud popmuusikuid, ooperilauljaid ja näitlejaid.\nKaks aastat **(2)** (tagasi, edasi, mööda) __(2)__ läksid sõbrad esimesele motomatkale. Selle eesmärk oli koguda abivajajatele **(3)** (raha, rahast, rahale) __(3)__\nIga aastaga on aga juurde tulnud firmasid, **(4)** (keda, kelleks, kes) __(4)__ selleks reisiks raha annetavad. Selle eest siis heategusid tehaksegi.\nTänavune motomatk viis mehed Pihkvasse. Seekord **(5)** (abistasid, leidsid, korjasid) __(5)__ nad kohalikku Jaani kirikut, mille taastamiseks oli kogutud 2500 eurot.\nMehed on Eesti küll otsast otsani **(6)** (läbi, kaudu, üle) __(6)__ sõitnud, aga ometi on alati midagi üllatavat. Palju on säilinud haruldasi paiku, mis on tõeliselt **(7)** (kaunite, kauneid, kaunid) __(7)__.\nIisakul külastati ka üht lastekodu, **(8)** (mida, mis, mille) __(8)__ tegi mehed kurvaks. See-eest rõõmustasid lapsed väga mootorratastega külaliste üle. Kõige **(9)** (parem, suurem, rohkem) __(9)__ huvi tekitas lastes mootorrattasõit.\nSõbrad leiavad, **(10)** (sest, et, kuid) __(10)__ see matk on ilus ettevõtmine. Selle tulemusel saavad näiteks kirikud uued aknad ja lapsed midagi vajalikku.","gap":2,"explanation":"","type":"text_gap","options":[],"accepted":["tagasi"],"correctIndex":-1},{"section":"1. ülesanne","group":"230