INSERT INTO official_exams (id, cefr_level, title, title_tr, title_en, source, questions, kind, skill, variant, sort_order, scoring, time_limit_minutes)
VALUES ($tt$testest-diagnostic-c1-writing-3$tt$, $tt$C1$tt$, $tt$C1 diagnoostest: kirjutamine (3. variant)$tt$, $tt$C1 tanı testi: yazma (3. varyant)$tt$, $tt$C1 diagnostic: writing (variant 3)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, $tt$[{"section":"1. ülesanne","group":"233-0","sourceTitle":"Kirjutamistesti 1. ülesanne, 1.-10. küsimus","prompt":"„Garage48 HUB on start-up ’i juhtidele ja **(1)** (tehnoloogiainimesed mõtlema avama kontor) __(1)__ või tööpind. Mujal maailmas on selline **(2)** (keskused kontseptsioon lai levima) ___, sellepärast otsustasime ka Eestis proovida,“ rääkis projekti üks autor Martin Villig.","context":"Täienda artiklit. Kirjuta sulgudes antud sõnad õiges vormis. Sõnade järjekorda ei ole vaja muuta, kuid mõne sõna liik võib muutuda.\n\n**Koht neile, kel pole oma kontorit**\n\nAlustavate IT-ettevõtete ühendus Garage48 hakkas detsembris Tallinna kesklinnas rentima ettevõtjatele mõeldud koostöötamise pinda, kuhu oodatakse inimesi nii Eestist kui ka välismaalt.\n„Garage48 HUB on start-up ’i juhtidele ja **(1)** (tehnoloogiainimesed mõtlema avama kontor) __(1)__ või tööpind. Mujal maailmas on selline **(2)** (keskused kontseptsioon lai levima) __(2)__, sellepärast otsustasime ka Eestis proovida,“ rääkis projekti üks autor Martin Villig.\nÜhtlasi saavad nad pakkuda Garage48 **(3)** (üritused koos käivad inimesed võimalus) __(3)__ ka nädala sees koos tööasju ajada. Samuti kasutavad projekti autorid ise **(4)** (välismaa aktiivne samasugune teenus) __(4)__. „See on hea mugav töökoht, kus on olemas internetiühendus ja kus on väga hea võimalus kohalike **(5)** (tehnoloogiavaldkond ettevõtjad kontakt saama) __(5)__,“ selgitas Villig.\nHUB on eelkõige **(6)** (mõtlema tehnoloogia, veebidisain ning programmeerimine valdkond firmad) __(6)__, kuid ukse taha ei jäeta ka teisi ettevõtjaid. „See on suunatud kas **(7)** (väiksed ettevõtted, kes puuduma vajadus oma kontor tegema) __(7)__, või neile, kes töötavad üksi kodus ja kel puudub sotsiaalne aspekt,“ rääkis Villig.\nPotentsiaalseteks klientideks on ka hulk ettevõtjaid, kes **(8)** (sõitma töö seoses Tartu vahepeal Tallinn ja vajama) __(8)__ osaliseks tööajaks pinda, lisas ta.\nTööd tehakse HUB-is kas **(9)** (laud taga, diivanid või kott-toolid istuma) __(9)__ ning eri korrustele mahub korraga töötama üle 30 inimese. Teenuse hinnad **(10)** (varieeruma vastav kasutamine tihedus) __(10)__ 10 eurost 90 euroni kuus.","gap":1,"explanation":"","type":"text_gap","options":[],"accepted":["tehnoloogiainimestele mõeldud avatud kontor"],"correctIndex":-1},{"section":"1. ülesanne","group":"233-0","sourceTitle":"Kirjutamistesti 1. ülesanne, 1.-10. küsimus","prompt":"„Garage48 HUB on start-up ’i juhtidele ja **(1)** (tehnoloogiainimesed mõtlema avama kontor) ___ või tööpind. Mujal maailmas on selline **(2)** (keskused kontseptsioon lai levima) __(2)__, sellepärast otsustasime ka Eestis proovida,“ rääkis projekti üks autor Martin Villig.","context":"Täienda artiklit. Kirjuta sulgudes antud sõnad õiges vormis. Sõnade järjekorda ei ole vaja muuta, kuid mõne sõna liik võib muutuda.\n\n**Koht neile, kel pole oma kontorit**\n\nAlustavate IT-ettevõtete ühendus Garage48 hakkas detsembris Tallinna kesklinnas rentima ettevõtjatele mõeldud koostöötamise pinda, kuhu oodatakse inimesi nii Eestist kui ka välismaalt.\n„Garage48 HUB on start-up ’i juhtidele ja **(1)** (tehnoloogiainimesed mõtlema avama kontor) __(1)__ või tööpind. Mujal maailmas on selline **(2)** (keskused kontseptsioon lai levima) __(2)__, sellepärast otsustasime ka Eestis proovida,“ rääkis projekti üks autor Martin Villig.\nÜhtlasi saavad nad pakkuda Garage48 **(3)** (üritused koos käivad inimesed võimalus) __(3)__ ka nädala sees koos tööasju ajada. Samuti kasutavad projekti autorid ise **(4)** (välismaa aktiivne samasugune teenus) __(4)__. „See on hea mugav töökoht, kus on olemas internetiühendus ja kus on väga hea võimalus kohalike **(5)** (tehnoloogiavaldkond ettevõtjad kontakt saama) __(5)__,“ selgitas Villig.