INSERT INTO official_exams (id, cefr_level, title, title_tr, title_en, source, questions, kind, skill, variant, sort_order, scoring, time_limit_minutes)
VALUES ($tt$testest-diagnostic-b2-reading-1$tt$, $tt$B2$tt$, $tt$B2 diagnoostest: lugemine (1. variant)$tt$, $tt$B2 tanı testi: okuma (1. varyant)$tt$, $tt$B2 diagnostic: reading (variant 1)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, $tt$[{"section":"1. ülesanne","group":"244-0","sourceTitle":"Lugemistesti 1. ülesanne, 1.-5. küsimus","prompt":"1. Jogurt mõjub hästi nägemisele. __(1)__","context":"Loe tekstilõike. Tekstilõikude kohta on esitatud väited. Otsusta, missuguse tekstilõigu kohta väide käib. A Maag Piimatööstuse Farmi jogurtisarja lisandusid uued kihilised jogurtid, mille topsi põhjas on moos. Valikus on nii mustika-, maasika-, virsiku- kui ka kirsijogurtid. Kihiliste jogurtite koostises on kakskümmend protsenti marjalisandit. \"Moos annab kooresele jogurtile maheda ja marjase maitse,\" kirjeldas Maag Piimatööstuse turundusjuht Kallaspoolik uusi tooteid.\nAllikas: Tarbija24 (29.11.2009) B Maag Piimatööstus toob turule uued seemnejogurtid. Uues sarjas on kaks maitset – pohla-linaseemne ja rabarberi-päevalilleseemne jogurtid. Tegemist uute, tervislike seemnejogurtitega. Ettevõttel on seni veel seemnetega jogurtid tootevalikust puudunud, mistõttu otsustatigi oma valikut laiendada. Päevalilleseemnetes on nii B- kui D- vitamiini, mineraale ja karotiini, mis mõjub hästi silmadele. Linaseemne õli sisaldab oomega-3 rasvhapet, mis tugevdab veresooni ning väljutab kolesterooli.\nAllikas: Toidutare (06.04.2009) C Mumuu funktsionaalsete jogurtite sarja on lisandunud pärnaõie-meejogurt. Nii pärnaõis kui ka lisatud mesi tugevdavad organismi ja on asendamatud abilised külmetuse ennetamisel ning samuti ka ravil. Rahustava toimega pärnaõis aitab kehast kiiresti eemaldada bakterite või gripiviiruste toodetavaid toksiine, mesi on aga ideaalne ja tõeline energiaallikas.\nAllikas: EPL (18.11.2005) **Näidis**\nJogurtisse on lisatud erinevaid marju.\nVastus: A\n\nMillise tekstilõigu kohta käib väide?\n\n1. Jogurt mõjub hästi nägemisele. __(1)__\n2. Jogurt aitab külmetamise korral. __(2)__\n3. Tootes on rohkesti vitamiine. __(3)__\n4. Tootevalikus on neli erinevat sorti jogurtit. __(4)__\n5. Jogurt annab palju jõudu. __(5)__","gap":1,"explanation":"","type":"multiple_choice","options":["A","B","C"],"correctIndex":1},{"section":"1. ülesanne","group":"244-0","sourceTitle":"Lugemistesti 1. ülesanne, 1.-5. küsimus","prompt":"2. Jogurt aitab külmetamise korral. __(2)__","context":"Loe tekstilõike. Tekstilõikude kohta on esitatud väited. Otsusta, missuguse tekstilõigu kohta väide käib. A Maag Piimatööstuse Farmi jogurtisarja lisandusid uued kihilised jogurtid, mille topsi põhjas on moos. Valikus on nii mustika-, maasika-, virsiku- kui ka kirsijogurtid. Kihiliste jogurtite koostises on kakskümmend protsenti marjalisandit. \"Moos annab kooresele jogurtile maheda ja marjase maitse,\" kirjeldas Maag Piimatööstuse turundusjuht Kallaspoolik uusi tooteid.\nAllikas: Tarbija24 (29.11.2009) B Maag Piimatööstus toob turule uued seemnejogurtid. Uues sarjas on kaks maitset – pohla-linaseemne ja rabarberi-päevalilleseemne jogurtid. Tegemist uute, tervislike seemnejogurtitega. Ettevõttel on seni veel seemnetega jogurtid tootevalikust puudunud, mistõttu otsustatigi oma valikut laiendada. Päevalilleseemnetes on nii B- kui D- vitamiini, mineraale ja karotiini, mis mõjub hästi silmadele. Linaseemne õli sisaldab oomega-3 rasvhapet, mis tugevdab veresooni ning väljutab kolesterooli.\nAllikas: Toidutare (06.04.2009) C Mumuu funktsionaalsete jogurtite sarja on lisandunud pärnaõie-meejogurt. Nii pärnaõis kui ka lisatud mesi tugevdavad organismi ja on asendamatud abilised külmetuse ennetamisel ning samuti ka ravil. Rahustava toimega pärnaõis aitab kehast kiiresti eemaldada bakterite või gripiviiruste toodetavaid toksiine, mesi on aga ideaalne ja tõeline energiaallikas.\nAllikas: EPL (18.11.2005) **Näidis**\nJogurtisse on lisatud erinevaid marju.\nVastus: A\n\nMillise tekstilõigu kohta käib väide?\n\n1. Jogurt mõjub hästi nägemisele. __(1)__\n2. Jogurt aitab külmeta